declare(strict_types=1);
function gc_payment_assign(array $event,int $order,array $actor):array {
 $o=one('SELECT * FROM pg_orders WHERE id=? FOR UPDATE',[$order]);if(!$o)throw new ApiError('Заказ не найден',404);
 if($event['order_id']!==null&&(int)$event['order_id']!==$order)throw new ApiError('Поступление уже связано с другим заказом',409);
 if($event['order_id']!==null)return ['orderId'=>$order,'status'=>$o['payment_status']];
 if($o['payment_status']==='confirmed')throw new ApiError('Заказ уже оплачен. Оставьте поступление для отдельной сверки.',409);
 $sum=(int)one('SELECT COALESCE(SUM(amount_minor),0) n FROM pg_bank_events WHERE order_id=?',[$order])['n']+(int)$event['amount_minor'];
 if($sum>(int)$o['total_minor'])throw new ApiError('Сумма превышает заказ. Требуется сверка переплаты; автоматический зачёт остановлен.',409);
 query('UPDATE pg_bank_events SET order_id=? WHERE id=?',[$order,$event['id']]);$state=$sum===(int)$o['total_minor']?'confirmed':'partial';query('UPDATE pg_orders SET payment_status=?,updated_at=? WHERE id=?',[$state,now(),$order]);
 if($state==='confirmed')query('INSERT INTO pg_bank_receipts(order_id,reference,amount_minor,confirmed_by,confirmed_at) VALUES(?,?,?,?,?)',[$order,'PG-EVENTS-'.gc_uuid(),$sum,$actor['id'],now()]);
 audit((int)$actor['id'],'gift_payment_matched',(string)$order,['eventId'=>$event['id'],'amount_minor'=>$event['amount_minor']]);return ['orderId'=>$order,'status'=>$state];
}
function gc_payment_record(array $d,array $actor):array {
 if(($d['bankVerified']??false)!==true)throw new ApiError('Подтвердите проверку банковской выписки');$ref=txt($d,'reference',150);$amount=minor($d['amount']??'',100000000000);if($amount<=0)throw new ApiError('Сумма должна быть положительной');$date=gc_date(txt($d,'bankDate',10));$order=(int)($d['orderId']??0);
 $old=one('SELECT * FROM pg_bank_events WHERE reference=? FOR UPDATE',[$ref]);if($old){if((int)$old['amount_minor']!==$amount||($order>0&&(int)$old['order_id']!==$order))throw new ApiError('Это основание уже записано с другими данными',409);return ['id'=>$old['id'],'duplicate'=>true];}
 if(one('SELECT reference FROM pg_bank_references WHERE reference=?',[$ref])||one('SELECT number FROM pm_operations WHERE bank_reference=?',[$ref]))throw new ApiError('Банковское основание уже использовано',409);
 $id=gc_uuid();query('INSERT INTO pg_bank_references(reference,event_kind,object_id,created_at) VALUES(?,?,?,?)',[$ref,'gift_bank_event',$id,now()]);query('INSERT INTO pg_bank_events(id,reference,amount_minor,bank_date,comment,actor_id,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$ref,$amount,$date,txt($d,'comment',3000,false),$actor['id'],now()]);
 if($order>0)gc_payment_assign(one('SELECT * FROM pg_bank_events WHERE id=? FOR UPDATE',[$id]),$order,$actor);audit((int)$actor['id'],'gift_bank_event_recorded',$id,['reference'=>$ref,'amount_minor'=>$amount]);return ['id'=>$id,'orderId'=>$order?:null];
}
function gc_validate_company(array $co,bool $onboarding=false):array {
 foreach(['fulfillmentAddress','name','reg','tax','address','role','director','authority','email','phone','bank','account','swift','goods','rules','issueTime','requestTime','validity','redemption','exchangeChannel'] as $field)$co[$field]=txt($co,$field,500);
 if(!filter_var($co['email'],FILTER_VALIDATE_EMAIL)||!filter_var($co['rules'],FILTER_VALIDATE_URL)||parse_url($co['rules'],PHP_URL_SCHEME)!=='https')throw new ApiError('Проверьте почту и HTTPS-ссылку на правила');
 if(!$onboarding)return $co;
 $co['categories']=gc_category_values($co);$co['category']=$co['categories'][0];
 $co['country']=strtoupper((string)($co['country']??'KG'));$co['countryName']=gc_country_name($co['country']);
 $co['fulfillmentCountry']=strtoupper((string)($co['fulfillmentCountry']??$co['country']));$co['fulfillmentCountryName']=gc_country_name($co['fulfillmentCountry']);
 if(($co['territoryConfirmed']??false)!==true)throw new ApiError('Подтвердите фактическое исполнение за пределами РФ и отсутствие электронных услуг');
 $co['nominals']=$co['nominals']??gc_default_nominals();if(!is_array($co['nominals'])||!count($co['nominals']))throw new ApiError('Выберите хотя бы один номинал карты');
 foreach($co['nominals'] as $n)if(!is_int($n)||!in_array($n,gc_allowed_nominals(),true))throw new ApiError('Недопустимый номинал карты');$co['nominals']=array_values(array_unique($co['nominals']));sort($co['nominals']);
 unset($co['territoryConfirmed']);gc_company_days($co);return $co;
}
function gc_save_supplier_company(string $id,mixed $raw,array $actor):array {
 if(!is_array($raw))throw new ApiError('Заполните реквизиты компании');
 $i=one('SELECT * FROM pg_issuers WHERE id=? FOR UPDATE',[$id]);if(!$i)throw new ApiError('Компания не найдена');
 $co=gc_validate_company($raw,true);$p=gc_company_program($co,json_decode($i['program_json'],true));
 if($co==json_decode($i['company_json'],true)&&$p==json_decode($i['program_json'],true))return ['issuerId'=>$id,'saved'=>true,'programSaved'=>true,'changed'=>false,'status'=>$i['status']];
 if(one('SELECT id FROM pg_orders WHERE issuer_id=? LIMIT 1',[$id]))throw new ApiError('Есть заказы: изменения реквизитов и программы оформляются отдельной новой редакцией',409);
 query("UPDATE pg_issuers SET name=?,country=?,company_json=?,program_json=?,status='review',contract_status='draft',contract_version=NULL,contract_hash=NULL,updated_at=? WHERE id=?",[$co['name'],$co['country'],json_encode($co,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),json_encode($p,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),now(),$id]);
 audit((int)$actor['id'],'gift_supplier_details_and_program_saved',$id);return ['issuerId'=>$id,'saved'=>true,'programSaved'=>true,'status'=>'review'];
}
